{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In a rat tissue-distribution study, the closely transferable analogue neferine distributed rapidly to peripheral organs but showed little brain exposure, directly indicating poor BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Compound 22h achieved high plasma concentrations but low brain and CSF levels after subcutaneous dosing in rats, attributed to P-gp efflux; this demonstrates that lipophilic amide-containing molecules can still have inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PET imaging of [11C]FJRD in mice and rats showed low brain uptake, supporting poor CNS penetration for a related heteroaromatic amide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Human PET imaging with [11C]AcL703 showed very low regional brain uptake (0.00028–0.00065% injected dose/mL), providing direct human evidence that related lipophilic amides can have inadequate BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "In rat pharmacokinetics, inhibitor 6 had an unbound brain/unbound plasma AUC ratio (Bu/Pu) of 0.08, a direct quantitative measure of poor brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In healthy humans, AMG 579 CSF concentrations were less than 5% of corresponding plasma concentrations at all timepoints, directly demonstrating inadequate CNS access for a related CNS-targeted amide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 11b in mice showed a brain/plasma ratio of only 8.4% at Cmax, indicating poor brain penetration despite systemic exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues consistently show poor brain/CSF exposure across species and methods, including low Bu/Pu, low brain/plasma ratios, low PET uptake, and efflux-mediated restriction. Despite a moderately favorable passive-permeability prior, the direct and transferable experimental evidence strongly supports inadequate CNS access for the query molecule.",
  "evidence_gaps": [
    "No direct experimental brain or CSF exposure measurement is available for the query molecule itself.",
    "The query's specific efflux-transporter phenotype has not been directly measured, although several close analogues show P-gp-related poor brain penetration.",
    "High estimated lipophilicity may lead to high plasma protein binding, which is not captured by the passive-permeability prior.",
    "Species differences between rodent and human BBB/CSF data could affect quantitative translation, but the direction is consistent across species."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

